<?php
namespace App\Http\Controllers\Operations;use App\Http\Controllers\Controller;use App\Models\{InventoryItem,MinibarConsumption,MinibarRoomItem,Room,Stay,Store};use App\Services\Operations\MinibarService;use Illuminate\Http\Request;
class MinibarController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('operations.minibar.index',['configs'=>MinibarRoomItem::with(['room','inventoryItem','store'])->where('property_id',$p)->latest()->paginate(60),'consumptions'=>MinibarConsumption::with(['room','roomItem.inventoryItem'])->where('property_id',$p)->latest('recorded_at')->limit(30)->get(),'rooms'=>Room::where('property_id',$p)->orderBy('room_number')->get(),'items'=>InventoryItem::where('property_id',$p)->where('is_active',1)->orderBy('name')->get(),'stores'=>Store::where('property_id',$p)->where('is_active',1)->orderBy('name')->get(),'stays'=>Stay::with(['room','guest'])->where('property_id',$p)->where('status','in_house')->get()]);}public function configure(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['room_id'=>'required|integer','inventory_item_id'=>'required|integer','store_id'=>'nullable|integer','par_quantity'=>'required|numeric|min:0','selling_price'=>'required|numeric|min:0']);Room::where('property_id',$p)->findOrFail($d['room_id']);InventoryItem::where('property_id',$p)->findOrFail($d['inventory_item_id']);MinibarRoomItem::updateOrCreate(['room_id'=>$d['room_id'],'inventory_item_id'=>$d['inventory_item_id']],$d+['property_id'=>$p,'is_active'=>true]);return back()->with('success','Mini-bar room item configured.');}public function consume(Request $r,MinibarService $service){$p=auth()->user()->property_id;$d=$r->validate(['stay_id'=>'required|integer','minibar_room_item_id'=>'required|integer','quantity'=>'required|numeric|min:0.001']);$stay=Stay::where('property_id',$p)->where('status','in_house')->findOrFail($d['stay_id']);$item=MinibarRoomItem::with('inventoryItem')->where('property_id',$p)->findOrFail($d['minibar_room_item_id']);$service->consume($stay,$item,(float)$d['quantity'],auth()->id());return back()->with('success','Mini-bar consumption posted to stock and guest folio.');}}
